enum_val.ev_driverval:
userdict /pt_contrast 0.50000000 put
userdict /settransfer {
 pop {
  userdict /pt_gamma known { userdict /pt_gamma get exp } if
  0.5 sub
  userdict /pt_contrast known { userdict /pt_contrast get mul } if
  0.5 add
  userdict /pt_brightness known { userdict /pt_brightness get add } if
  0 max 1 min
 } systemdict /settransfer get exec
} bind put
userdict /setcolortransfer { pop pop pop pop {} settransfer } bind put
{} settransfer

